SELECT cd_gender, c_birth_year, SUM(cr_return_amount) AS total_return_amount, COUNT(*) AS return_count FROM catalog_returns INNER JOIN customer ON catalog_returns.cr_refunded_customer_sk = customer.c_customer_sk INNER JOIN customer_demographics ON customer.c_current_cdemo_sk = customer_demographics.cd_demo_sk WHERE catalog_returns.cr_returned_date_sk >= 2451034 AND catalog_returns.cr_returned_date_sk <= 2450996 AND c_birth_year = 1988 GROUP BY cd_gender, c_birth_year
